              I agree to the <a href="#terms-summary">Terms of Use</a>
              <span class="required-marker" aria-hidden="true">*</span>
              <span class="sr-only">required</span>
            </label>
          </div>
          <p id="terms-help" class="helper-text">You must accept the terms to create and manage your account.</p>
          <p id="terms-error" class="error-text" hidden>Error: Agree to the Terms of Use to continue.</p>
        </div>

        <button type="submit">Continue</button>
        <p id="form-status" class="status" aria-live="polite"></p>
      </form>

      <p id="terms-summary" class="sr-only">Terms of Use summary: use the service responsibly and follow account policies.</p>
    </section>
  </main>

  <script>
    const form = document.querySelector("#consent-form");
    const checkbox = document.querySelector("#agree-terms");
    const error = document.querySelector("#terms-error");
    const status = document.querySelector("#form-status");

    function setCheckboxValidity(isValid) {
      checkbox.setAttribute("aria-invalid", String(!isValid));
      error.hidden = isValid;
    }

    checkbox.addEventListener("change", () => {
      setCheckboxValidity(checkbox.checked);
      if (checkbox.checked) {
        status.textContent = "";
      }
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!checkbox.checked) {
        setCheckboxValidity(false);
        status.textContent = "";
        checkbox.focus();
        return;
      }

      setCheckboxValidity(true);
      status.textContent = "Thanks. Your consent has been recorded.";
      form.reset();
    });
