      <p class="intro">Confirm that you accept the product terms before moving forward.</p>

      <form id="consent-form" novalidate>
        <p class="required-note"><span aria-hidden="true">*</span> Required field</p>

        <div class="form-field">
          <div class="checkbox-row">
            <input
              id="agree-terms"
              name="agreeTerms"
              type="checkbox"
              required
              aria-describedby="terms-help"
            >
            <label for="agree-terms">
              I agree to the Terms of Use
              <span class="required-marker" aria-hidden="true">*</span>
              <span class="sr-only">required</span>
            </label>
          </div>
          <p id="terms-help" class="helper-text">You must accept the terms to create and manage your account.</p>
          <p id="terms-error" class="error-text" hidden>Error: Agree to the Terms of Use to continue.</p>
